#!/usr/bin/env python3
"""
Shopify Dev MCP Provider for Promptfoo using OpenAI Agents SDK

This provider uses the OpenAI Agents SDK with MCP tools for Shopify development assistance.

Features:
- OpenAI Agents SDK with access to Shopify Dev MCP tools
- Automatic tool call trajectory tracking
- Automatic LLM token usage tracking from agent responses

Configuration:
- model: The OpenAI model to use (default: "gpt-5")
- apiKey: OpenAI API key (can also use OPENAI_API_KEY env var)
- baseURL: API base URL (default: https://proxy.shopify.ai/v1)
- liquidValidationMode: Liquid validation mode - "partial" (validate code blocks only) or "full" (validate theme files)
  When set to "full", creates a temporary theme directory for validate_theme tool
  Default: "partial"

Response Format:
The provider returns a standard promptfoo response with:
- output: The formatted response with tool call trajectory
- tokenUsage: Token usage statistics (total, prompt, completion)
"""

import json
import os
import sys
import tempfile
from pathlib import Path
from typing import Any, Dict

# Add parent directory to path for imports
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from agents import (
    Agent,
    ItemHelpers,
    OpenAIResponsesModel,
    Runner,
)
from agents.mcp import MCPServerStdio
from openai import AsyncOpenAI


def create_dev_assistant_agent(
    mcp_server: MCPServerStdio,
    model: str,
    client: AsyncOpenAI,
) -> Agent:
    """Create the Dev Assistant agent with MCP tools."""
    # Load instructions from the instructions.txt file
    instructions_path = Path(__file__).parent / "instructions.txt"
    with open(instructions_path, "r") as f:
        instructions = f.read()

    # Use OpenAIResponsesModel with the model and client
    model_instance = OpenAIResponsesModel(model=model, openai_client=client)

    return Agent(
        name="Shopify Dev Assistant",
        instructions=instructions,
        model=model_instance,
        mcp_servers=[mcp_server],
    )


def create_theme_directory() -> str:
    """Create a temporary Shopify theme directory with standard structure.

    Returns:
        Path to the created temporary directory
    """
    temp_dir = Path(tempfile.mkdtemp(prefix="liquid_theme_test_"))

    # Standard Shopify theme directories
    theme_dirs = [
        "assets",
        "blocks",
        "config",
        "layout",
        "locales",
        "sections",
        "snippets",
        "templates",
        "templates/customers",
    ]

    for dir_name in theme_dirs:
        (temp_dir / dir_name).mkdir(parents=True, exist_ok=True)

    return str(temp_dir)


def create_mcp_server(config: Dict[str, Any]) -> MCPServerStdio:
    """Create the MCP server for Shopify Dev tools."""
    # Always use the locally built version
    # Navigate from providers directory to the dist directory
    dist_path = Path(__file__).parent.parent.parent / "dist" / "index.js"

    # Build environment variables
    env = {
        "OPT_OUT_INSTRUMENTATION": "true",
        "STOREFRONT_WEB_COMPONENTS": "true",
        "DEV": os.environ.get("DEV", "false"),
        "USE_LEGACY_SEARCH": os.environ.get("USE_LEGACY_SEARCH", "false"),
    }

    # Get validation mode from config - use it for LIQUID_VALIDATION_MODE
    liquidValidationMode = config.get("liquidValidationMode", "partial")
    env["LIQUID_VALIDATION_MODE"] = liquidValidationMode

    if "envVars" in config:
        for env_var_name, env_var_value in config["envVars"].items():
            env[env_var_name] = str(env_var_value)

    return MCPServerStdio(
        params={
            "command": "node",
            "args": [str(dist_path)],
            "env": env,
        },
        client_session_timeout_seconds=240,
    )


async def run_agent(prompt: str, config: Dict[str, Any]) -> Dict[str, Any]:
    """Run the agent with streaming and collect output."""
    # Parse configuration
    model = config.get("model", "gpt-5")
    api_key = config.get("apiKey") or os.environ.get("OPENAI_API_KEY")
    base_url = config.get("baseURL", "https://proxy.shopify.ai/v1")

    if not api_key:
        raise ValueError(
            "No API key provided. Please set OPENAI_API_KEY environment variable "
            "or provide apiKey in config.\n"
            "To get an API key:\n"
            "1. Visit https://proxy.shopify.ai\n"
            "2. Follow the instructions to obtain your API key\n"
            "3. Export it: export OPENAI_API_KEY='your-key-here'"
        )

    # Create OpenAI client
    client = AsyncOpenAI(api_key=api_key, base_url=base_url)

    # Initialize tracking
    output_lines = []
    current_section = None
    token_usage = {"total": 0, "prompt": 0, "completion": 0}

    # Setup theme directory for full validation mode
    temp_theme_path = None
    liquidValidationMode = config.get("liquidValidationMode", "partial")

    if liquidValidationMode == "full":
        temp_theme_path = create_theme_directory()
        # Modify prompt to include the theme directory path
        prompt = f"""Your Shopify theme directory has been pre-created at: {temp_theme_path}

Use this exact path for the 'absoluteThemePath' parameter when calling validate_theme.

{prompt}"""

    # Create MCP server and agent
    async with create_mcp_server(config) as mcp_server:
        agent = create_dev_assistant_agent(
            mcp_server, model, client
        )

        try:
            # Create the stream
            stream = Runner.run_streamed(agent, input=prompt, max_turns=40)

            # Collect all events
            collected_events = []

            async for event in stream.stream_events():
                collected_events.append(event)

                # Collect token usage from raw responses
                if hasattr(event, "type") and event.type == "raw_response_event":
                    if hasattr(event.data, "usage"):
                        token_usage["total"] += getattr(event.data.usage, "total_tokens", 0)
                        token_usage["prompt"] += getattr(event.data.usage, "prompt_tokens", 0)
                        token_usage["completion"] += getattr(event.data.usage, "completion_tokens", 0)

            # Process collected events to build output
            for event in collected_events:
                try:
                    if hasattr(event, "type") and event.type == "run_item_stream_event":
                        item = event.item

                        if item.type == "message_output_item":
                            # Assistant response
                            if current_section != "response":
                                if output_lines:
                                    output_lines.append("")
                                    output_lines.append("=" * 80)
                                output_lines.append("🤖 ASSISTANT RESPONSE")
                                output_lines.append("-" * 80)
                                current_section = "response"

                            # Extract message text
                            try:
                                message_text = ItemHelpers.text_message_output(item)
                                output_lines.append(message_text)
                            except Exception:
                                # Fallback extraction
                                if hasattr(item, "message") and hasattr(item.message, "content"):
                                    for content in item.message.content:
                                        if hasattr(content, "text"):
                                            output_lines.append(content.text)
                                        else:
                                            output_lines.append(str(content))

                        elif item.type == "tool_call_item":
                            # Tool call
                            if current_section != "tool":
                                if output_lines:
                                    output_lines.append("")
                                    output_lines.append("=" * 80)
                                output_lines.append("🔧 TOOL INTERACTION")
                                output_lines.append("-" * 80)
                                current_section = "tool"

                            tool_name = getattr(item.raw_item, "name", "unknown")
                            tool_args = getattr(item.raw_item, "arguments", {})
                            output_lines.append(f"→ Called: {tool_name} with arguments: {tool_args}")

                        elif item.type == "tool_call_output_item":
                            # Tool output
                            if current_section != "tool":
                                if output_lines:
                                    output_lines.append("")
                                    output_lines.append("=" * 80)
                                output_lines.append("🔧 TOOL INTERACTION")
                                output_lines.append("-" * 80)
                                current_section = "tool"

                            output_lines.append("")
                            output_lines.append("← Tool Output:")
                            output_lines.append("-" * 40)

                            # Parse tool output
                            try:
                                output_data = (
                                    json.loads(item.output)
                                    if isinstance(item.output, str)
                                    else item.output
                                )
                                if isinstance(output_data, dict) and "text" in output_data:
                                    output_lines.append(output_data["text"])
                                else:
                                    output_lines.append(str(item.output))
                            except (json.JSONDecodeError, TypeError):
                                output_lines.append(str(item.output))

                            output_lines.append("-" * 40)

                except Exception:
                    # Log but continue processing
                    continue

        except Exception as e:
            # Handle errors gracefully
            output_lines.append(f"Error: {str(e)}")

    # Build final output
    if output_lines:
        output_lines.append("")
        output_lines.append("=" * 80)

    output = "\n".join(output_lines) if output_lines else ""

    # Ensure we have at least minimal token usage
    if token_usage["total"] == 0:
        token_usage = {"total": 1, "prompt": 1, "completion": 0}

    return {
        "output": output,
        "tokenUsage": token_usage,
    }


async def call_api(prompt: str, options: Dict[str, Any], context: Dict[str, Any]) -> Dict[str, Any]:
    """Main entry point for promptfoo provider."""
    try:
        # Merge options and context vars
        config = {**options, **context.get("vars", {})}

        # Run the agent
        result = await run_agent(prompt, config)

        return result

    except Exception as e:
        return {
            "error": str(e),
            "output": f"Error: {str(e)}",
            "tokenUsage": {"total": 1, "prompt": 1, "completion": 0}
        }
